() => {
  const invText = document.getElementById('inv').innerText.replace(/\n/g,' ');
  const btns = Array.from(document.querySelectorAll('.zbtn'));
  const vip = btns.find(b=>b.dataset.code==='VIP2WCX');
  vip.click();
  const rowN = document.getElementById('rowN').innerText;
  const foot = document.getElementById('footInfo').innerText;
  const rows = document.querySelectorAll('#tbody tr').length;
  const skus = Array.from(document.querySelectorAll('#tbody tr td:nth-child(5)')).slice(0,3).map(t=>t.innerText.trim());
  return { invText, rowN, foot, rows, skus, urgentBtnClass: vip.className };
}

