/* ---------- 一键催发卡片（发现→派活；离线可用，clipboard 不可用则退回下载） ---------- */
$('#dispatchBtn').onclick=async ()=>{
  const rows=O.filter(o=>o.severity>=40).sort((a,b)=>b.severity-a.severity);
  if(!rows.length){ toast('当前无需立即处理的单'); return; }
  const cd=(r)=> r==null?'—':(r<0?`超期${Math.abs(r).toFixed(1)}h`:`剩${r.toFixed(1)}h`);
  const lines=[`【发货哨兵·催发 ${(D.meta.reference_now||'').slice(0,16)}】${rows.length} 单需立即处理：`,''];
  rows.forEach((o,i)=>{
    lines.push(`${i+1}. ${o['包裹号']} ${o['平台']}/${o['店铺']} ${o['SKU']} ${o['品名']||''}`);
    lines.push(`   仓库:${o['仓库']} 渠道:${o['发货渠道']||'（空）'} 倒计时:${cd(o.remaining_h)} 异常:${o.anomalies.map(t=>D.rules[t].name).join('/')}`);
    if(o.ai&&o.ai.action) lines.push(`   建议处置:${o.ai.action}`);
  });
  lines.push('','（发货哨兵只读生成 · 请到赛狐/Temu 处理）');
  const text=lines.join('\n');
  try{ await navigator.clipboard.writeText(text); toast('✅ 催发卡片已复制，可粘贴到企业微信/钉钉'); }
  catch(e){ const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.download='催发卡片_'+(D.meta.reference_now||'').slice(0,10)+'.txt';a.click(); toast('已导出 催发卡片.txt（可粘贴群里）'); }
};

/* ---------- 💰 价值估算（保守，可替换为真实基线） ---------- */
