    {v:`~${savedHrs} 小时/月`,l:'省下的人工核对',s:`三系统逐单核对 ${R.minManual}→${R.minSentinel} 分钟/天（${R.workdays} 工作日）`},
    {v:`${k.total_orders} → ${k.actionable} 单`,l:'注意力聚焦',s:`${focusPct}% 的单确定无恙、无需逐一核对`},
    {v:`${D.inventory.temu_zero_stock.length} + ${critCombo.length} 单`,l:'提前拦下的风险',s:`断货预警 + 卡仓无法出库——单看一个系统都发现不了`},
  ];
  $('#roi').innerHTML=cells.map(x=>`<div class="roicell"><div class="roiv">${x.v}</div><div class="roil">${esc(x.l)}</div><div class="rois">${esc(x.s)}</div></div>`).join('')
