  btn.click();
  await new Promise(r => setTimeout(r, 500));
  const t = document.getElementById('toast');
  // also read clipboard if available
  let clip = '(n/a)';
  try { clip = (await navigator.clipboard.readText()).split('\n').slice(0,4).join(' / '); } catch(e) { clip = 'clipboard-blocked: ' + e.name; }
  return { toastText: t.innerText, toastShown: t.classList.contains('show'), clipboardHead: clip };
}

